#!/usr/bin/env python3
"""Generate the public feature catalog from docs/product/TRACEABILITY.md."""

from __future__ import annotations

import argparse
import re
import sys
from dataclasses import dataclass
from pathlib import Path


ROOT = Path(__file__).resolve().parents[1]
DEFAULT_SOURCE = ROOT / "docs" / "product" / "TRACEABILITY.md"
DEFAULT_OUTPUT = ROOT / "docs" / "features"
STATUSES = ("Implemented", "Partial", "Planned", "Blocked")
GENERATED_NOTICE = (
    "<!-- Generated by scripts/generate_feature_docs.py. "
    "Edit docs/product/TRACEABILITY.md, then run `make docs-generate`. -->"
)


@dataclass(frozen=True)
class Feature:
    label: str
    title: str
    source: str
    implementation: str
    tests: str
    status: str
    status_detail: str

    @property
    def anchor(self) -> str:
        value = re.sub(r"[^a-z0-9]+", "-", f"{self.label} {self.title}".lower())
        return value.strip("-")


def normalize_status(value: str) -> str:
    lowered = value.strip().lower()
    for status in STATUSES:
        if lowered.startswith(status.lower()):
            return status
    raise ValueError(f"Unsupported traceability status: {value!r}")


def parse_traceability(path: Path) -> list[Feature]:
    lines = path.read_text(encoding="utf-8").splitlines()
    features: list[Feature] = []
    seen_labels: set[str] = set()
    index = 0
    while index < len(lines):
        header = lines[index]
        is_feature_table = header in {
            "| Requirement label | Source | Implementation files | Test coverage | Status |",
            "| Requirement | Source | Planning/spec files | Runtime tests | Status |",
        }
        if not is_feature_table:
            index += 1
            continue
        index += 2
        while index < len(lines) and lines[index].startswith("|"):
            line = lines[index]
            cells = [cell.strip() for cell in line.strip().strip("|").split("|")]
            if len(cells) != 5:
                raise ValueError(f"Expected five traceability columns: {line}")
            requirement, source, implementation, tests, status_detail = cells
            label, separator, title = requirement.partition(" ")
            if not separator or not label or not title:
                raise ValueError(
                    f"Requirement label must include a title: {requirement!r}"
                )
            if label in seen_labels:
                raise ValueError(f"Duplicate traceability label: {label}")
            seen_labels.add(label)
            features.append(
                Feature(
                    label=label,
                    title=title,
                    source=source,
                    implementation=implementation,
                    tests=tests,
                    status=normalize_status(status_detail),
                    status_detail=status_detail,
                )
            )
            index += 1
    if not features:
        raise ValueError(f"No features parsed from {path}")
    return features


def badge(status: str) -> str:
    return (
        f'<span class="boss-status boss-status--{status.lower()}">'
        f"{status}</span>"
    )


def render_index(features: list[Feature]) -> str:
    counts = {status: sum(feature.status == status for feature in features) for status in STATUSES}
    lines = [
        GENERATED_NOTICE,
        "",
        "# Feature catalog",
        "",
        "This catalog is generated from the canonical product traceability ledger. It is the public view of what BOSS implements today and what remains planned or blocked.",
        "",
        '<div class="feature-summary">',
    ]
    for status in STATUSES:
        lines.extend(
            [
                "  <div>",
                f"    {badge(status)}",
                f"    <strong>{counts[status]}</strong>",
                "  </div>",
            ]
        )
    lines.extend(
        [
            "</div>",
            "",
            "| Feature | Status | Source |",
            "|---|---|---|",
        ]
    )
    for feature in features:
        page = feature.status.lower()
        lines.append(
            f"| [{feature.label} — {feature.title}]({page}.md#{feature.anchor}) "
            f"| {badge(feature.status)} | {feature.source} |"
        )
    lines.extend(
        [
            "",
            "Status is descriptive, not promotional: `Implemented` means a runtime path and automated coverage are both present; `Blocked` means an external dependency, credential, configuration, or explicit approval is still required.",
            "",
        ]
    )
    return "\n".join(lines)


def render_status_page(status: str, features: list[Feature]) -> str:
    selected = [feature for feature in features if feature.status == status]
    lines = [
        GENERATED_NOTICE,
        "",
        f"# {status} features",
        "",
        f"{badge(status)} **{len(selected)} feature{'s' if len(selected) != 1 else ''}**",
        "",
    ]
    if not selected:
        lines.extend(["No features currently have this status.", ""])
        return "\n".join(lines)
    for feature in selected:
        lines.extend(
            [
                f"## {feature.label} — {feature.title} {{#{feature.anchor}}}",
                "",
                badge(feature.status),
                "",
                f"**Source:** {feature.source}",
                "",
                f"**Implementation:** {feature.implementation}",
                "",
                f"**Automated evidence:** {feature.tests}",
                "",
                f"**Ledger detail:** {feature.status_detail}",
                "",
            ]
        )
    return "\n".join(lines)


def desired_files(features: list[Feature]) -> dict[str, str]:
    rendered = {"index.md": render_index(features)}
    rendered.update(
        {
            f"{status.lower()}.md": render_status_page(status, features)
            for status in STATUSES
        }
    )
    return rendered


def generate(source: Path, output: Path, *, check: bool) -> int:
    files = desired_files(parse_traceability(source))
    stale: list[str] = []
    for filename, content in files.items():
        target = output / filename
        expected = content.rstrip() + "\n"
        if check:
            if not target.exists() or target.read_text(encoding="utf-8") != expected:
                try:
                    stale.append(str(target.relative_to(ROOT)))
                except ValueError:
                    stale.append(str(target))
            continue
        output.mkdir(parents=True, exist_ok=True)
        target.write_text(expected, encoding="utf-8")
    if stale:
        print("Generated feature documentation is stale:", file=sys.stderr)
        for path in stale:
            print(f"  - {path}", file=sys.stderr)
        print("Run `make docs-generate` and commit the result.", file=sys.stderr)
        return 1
    if check:
        print(f"Feature documentation is current ({len(files)} generated pages).")
    else:
        print(f"Generated {len(files)} feature documentation pages in {output}.")
    return 0


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--check", action="store_true")
    parser.add_argument("--source", type=Path, default=DEFAULT_SOURCE)
    parser.add_argument("--output", type=Path, default=DEFAULT_OUTPUT)
    args = parser.parse_args()
    return generate(args.source, args.output, check=args.check)


if __name__ == "__main__":
    raise SystemExit(main())
